// The full bundled icon sets (icon-packs/, generated by scripts/build-icons.mjs): names load on first use and
// artwork loads per chunk, so a diagram pulls in only the chunks its icons are in. Everything is a local build
// asset; nothing is fetched from outside.
//
// Layout calls `prepareIcons` (async) before it measures, so by the time a scene is painted every icon it names
// is loaded and `packIcon` (sync) can answer. Before that, `iconFor` falls back to the small built-in set.

import { packChunk } from './icon-hash.ts';
import { PACK_LOADERS, PACK_SETS } from './icon-packs/loaders.ts';

export type PackSet = 'lucide' | 'simple' | 'aws' | 'azure' | 'gcp';
/** One chunk file: key → [viewBox, path data or sanitized SVG markup, brand colour]. */
export type PackChunk = Record<string, [vb: string, body: string, hex?: string]>;

export interface PackIcon {
  set: PackSet;
  key: string;
  /** stroke: outline path (Lucide). fill: one filled path (logos). art: the vendor's own multi-colour drawing. */
  kind: 'stroke' | 'fill' | 'art';
  vb: string;
  body: string;
  hex?: string;
}

type Names = typeof import('./icon-packs/names.ts');

let names: Names | undefined;
let namesLoad: Promise<Names> | undefined;
const chunks = new Map<string, PackChunk>();
const chunkLoads = new Map<string, Promise<void>>();

/** Load the name index (once). */
export function loadIconNames(): Promise<Names> {
  namesLoad ??= import('./icon-packs/names.ts').then((m) => (names = m));
  return namesLoad;
}

/** The name index when loaded, else undefined. */
export const iconNamesLoaded = (): Names | undefined => names;

/** Normalised lookup key: lower-case, spaces and underscores as dashes. */
export const iconKey = (name: string): string => name.trim().toLowerCase().replace(/[\s_]+/g, '-');

/** set + key for a name in the index, or undefined. Own-property lookups only (`constructor` is not an icon). */
export function resolveName(name: string): { set: PackSet; key: string } | undefined {
  if (!names) return undefined;
  const n = iconKey(name);
  if (!Object.hasOwn(names.ICON_NAMES, n)) return undefined;
  const v = names.ICON_NAMES[n]!;
  const i = v.indexOf(':');
  return i < 0 ? { set: v as PackSet, key: n } : { set: v.slice(0, i) as PackSet, key: v.slice(i + 1) };
}

const chunkId = (set: PackSet, key: string): string => `${set}-${packChunk(key, PACK_SETS[set].chunks)}`;

function loadChunk(id: string): Promise<void> {
  let p = chunkLoads.get(id);
  if (!p) {
    const loader = PACK_LOADERS[id];
    p = loader ? loader().then((m) => void chunks.set(id, m.default)) : Promise.resolve();
    chunkLoads.set(id, p);
  }
  return p;
}

/** Load the index and the artwork chunks for these icon names. Unknown names are skipped. */
export async function loadIcons(list: Iterable<string>): Promise<void> {
  await loadIconNames();
  const ids = new Set<string>();
  for (const name of list) {
    const r = resolveName(name);
    if (r) ids.add(chunkId(r.set, r.key));
  }
  await Promise.all([...ids].map(loadChunk));
}

/** The artwork for a name, if its chunk is loaded. */
export function packIcon(name: string): PackIcon | undefined {
  const r = resolveName(name);
  if (!r) return undefined;
  const chunk = chunks.get(chunkId(r.set, r.key));
  if (!chunk || !Object.hasOwn(chunk, r.key)) return undefined;
  const [vb, body, hex] = chunk[r.key]!;
  return { set: r.set, key: r.key, kind: PACK_SETS[r.set].kind, vb, body, hex };
}

/** Every icon name with its set and search title, for the picker. */
export async function allIconNames(): Promise<{ name: string; set: PackSet; key: string; title?: string }[]> {
  const n = await loadIconNames();
  return Object.keys(n.ICON_NAMES).map((name) => {
    const r = resolveName(name)!;
    return { name, ...r, title: n.ICON_TITLES[`${r.set}:${r.key}`] };
  });
}
